refentry.refsect1:
&reftitle.description;
public static Yaf_ApplicationnullYaf_Application::app
Obtém a instância de Yaf_Application. Alternativamente, Yaf_Dispatcher::getApplication também pode ser usado.

&reftitle.returnvalues;

 A instância de Yaf_Application, ou &null; se nenhuma
 aplicação tiver sido inicializada ainda.

  &reftitle.examples;

   Exemplo de Yaf_Application::app


<?php
/* index.php, a entrada da aplicação */
$config = new Yaf_Config_Ini(__DIR__ . "/conf/application.ini", "product");
$application = new Yaf_Application($config);
$application->bootstrap()->run();
?>




   Obtendo a instância da aplicação em outro local


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        /* Yaf_Application::app() é um apelido de getInstance() */
        $app = Yaf_Application::app();

        var_dump($app->environ());
        var_dump(Yaf_Application::getInstance() === $app);

        return false;
    }
}
?>


   &example.outputs.similar;


string(7) "product"
bool(true)
